/* Loads the rebuilt interface, visual identity, reference-match layer, and offline JSZip build. */
(() => {
  'use strict';

  const VERSION = '2026-08-06-reference-1';
  const head = document.head;
  const nativeAppendChild = head.appendChild.bind(head);

  head.appendChild = node => {
    if (node?.tagName === 'LINK') {
      const href = node.getAttribute('href') || '';
      if (href.includes('theme-oriental-r4.css')) {
        node.href = `./theme-base.css?v=${VERSION}`;
        node.dataset.orientalTheme = 'true';
      }
      if (href.includes('fonts.googleapis.com') && href.includes('Material+Symbols')) {
        return node;
      }
    }
    return nativeAppendChild(node);
  };

  const rebuiltUi = document.createElement('script');
  rebuiltUi.src = `./ui-rebuild.js?v=${VERSION}`;
  rebuiltUi.async = false;
  rebuiltUi.addEventListener('load', () => {
    const approvedTheme = document.createElement('link');
    approvedTheme.rel = 'stylesheet';
    approvedTheme.href = `./theme-oriental.css?v=${VERSION}`;
    approvedTheme.dataset.approvedTheme = 'true';
    nativeAppendChild(approvedTheme);

    const luxuryTheme = document.createElement('link');
    luxuryTheme.rel = 'stylesheet';
    luxuryTheme.href = `./theme-ney-luxury.css?v=${VERSION}`;
    luxuryTheme.dataset.luxuryNeyTheme = 'true';
    nativeAppendChild(luxuryTheme);

    const referenceTheme = document.createElement('link');
    referenceTheme.rel = 'stylesheet';
    referenceTheme.href = `./theme-reference-match.css?v=${VERSION}`;
    referenceTheme.dataset.referenceMatchTheme = 'true';
    nativeAppendChild(referenceTheme);

    const enhancements = document.createElement('script');
    enhancements.src = `./ui-enhancements.js?v=${VERSION}`;
    enhancements.async = false;
    nativeAppendChild(enhancements);
  });
  nativeAppendChild(rebuiltUi);

  const restoreAppend = () => { head.appendChild = nativeAppendChild; };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => setTimeout(restoreAppend, 0), { once: true });
  } else {
    setTimeout(restoreAppend, 1000);
  }

  document.write('<script src="vendor/jszip-core.min.js"><\/script>');
})();
